/**
 * Cache tag vocabulary and revalidation helpers.
 *
 * Next 16 requires a cache-life profile as the second argument to
 * `revalidateTag`, which is exactly the kind of API change that rots when it
 * is spelled out at forty call sites. Server Actions call
 * `revalidateTagged([...])` and never import `next/cache` themselves.
 */
import { revalidateTag } from "next/cache";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

/** The cache-life profiles this app uses, by how stale a read may be. */
export const CACHE_PROFILES: Readonly<
  Record<"seconds" | "minutes" | "hours", string>
> = {
  seconds: "seconds",
  minutes: "minutes",
  hours: "hours",
};

export function orgTag(orgId: OrgId): string {
  return `org:${orgId}`;
}

export function projectTag(projectId: ProjectId): string {
  return `project:${projectId}`;
}

export function issueTag(issueId: IssueId): string {
  return `issue:${issueId}`;
}

/**
 * Invalidates every supplied tag under one profile, de-duplicating first so a
 * caller can splice together tag lists without worrying about repeats.
 */
export function revalidateTagged(
  tags: readonly string[],
  profile: string = CACHE_PROFILES.minutes,
): void {
  for (const tag of new Set(tags)) {
    if (tag === "") continue;
    revalidateTag(tag, profile);
  }
}
/**
 * Label CRUD and the issue↔label assignment used by the picker.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope
 */
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as labelRepo from "@/server/repositories/label-repository";
import { orgResource } from "./_support";
import type { CreateLabelInput, UpdateLabelInput } from "@/schemas/label";
import type { LabelId, OrgId } from "@/types/common";
import type { IssueLabel } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Labels are org-wide metadata, so they follow the project permissions. */
export async function listLabels(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly IssueLabel[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:read", orgResource(orgId));
  return labelRepo.listLabels(orgId);
}

export async function createLabel(
  actor: Actor,
  input: CreateLabelInput,
): Promise<IssueLabel> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:update", orgResource(input.orgId));

  const existing = await labelRepo.listLabels(input.orgId);
  if (existing.some((label) => label.name === input.name)) {
    throw new Error(`A label named "${input.name}" already exists`);
  }

  return labelRepo.insertLabel(input);
}

export async function updateLabel(
  actor: Actor,
  input: UpdateLabelInput,
