/**
 * `private` projects are invisible to anyone who is not an admin/owner, platform
 * staff, the project's lead or an explicit project member.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectMemberRepo from "@/server/repositories/project-member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { NotFoundError } from "@/server/services/_support";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Comment } from "@/types/comment";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

let cleanup: () => void;
let tenant: Tenant;
let secret: Project;
let secretIssue: Issue;
let secretComment: Comment;
let openIssue: Issue;

/** A second member and viewer, so membership can be granted to one of them. */
let outsider: Actor;
let staff: Actor;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("privateproj", "growth");

  secret = await projectRepo.insertProject({
    orgId: tenant.org.id,
    name: "Secret",
    slug: "secret",
    key: "SEC",
    description: null,
    visibility: "private",
    leadId: tenant.userIds.admin,
    color: "#6366f1",
    targetDate: null,
  });

  secretIssue = await issueService.createIssue(
    tenant.actors.admin,
    issueInput(tenant.org.id, secret.id, { title: "Hidden issue" }),
  );
  secretComment = await commentService.createComment(tenant.actors.admin, {
    orgId: tenant.org.id,
    issueId: secretIssue.id,
    body: "Hidden comment",
    parentId: null,
    mentionedUserIds: [],
  });
  openIssue = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Visible issue" }),
  );

  outsider = tenant.actors.member;
  staff = { ...tenant.actors.viewer, isPlatformStaff: true };
});

afterAll(() => {
  cleanup();
});

async function rejectsNotFound(promise: Promise<unknown>): Promise<void> {
  await expect(promise).rejects.toBeInstanceOf(NotFoundError);
}

describe("canViewProject", () => {
  it("lets everyone see org and public projects", async () => {
    for (const visibility of ["org", "public"] as const) {
      const project = { ...secret, visibility };
      expect(await projectService.canViewProject(tenant.actors.viewer, project)).toBe(true);
    }
  });

  it("admits admins, owners, staff and the lead of a private project", async () => {
    expect(await projectService.canViewProject(tenant.actors.owner, secret)).toBe(true);
    expect(await projectService.canViewProject(tenant.actors.admin, secret)).toBe(true);
    expect(await projectService.canViewProject(staff, secret)).toBe(true);
    // The admin is also the lead; make the lead a plain member to isolate that rule.
    const led = { ...secret, leadId: tenant.userIds.member };
    expect(await projectService.canViewProject(tenant.actors.member, led)).toBe(true);
  });

  it("hides a private project from everyone else", async () => {
    expect(await projectService.canViewProject(tenant.actors.member, secret)).toBe(false);
    expect(await projectService.canViewProject(tenant.actors.viewer, secret)).toBe(false);
  });

  it("never admits an actor from another organization", async () => {
    const other = await createTenant("privateother", "growth");
    expect(await projectService.canViewProject(other.actors.owner, secret)).toBe(false);
  });
});

describe("private project — reads", () => {
  it("looks like a missing project, issue, board and thread to an outsider", async () => {
    await rejectsNotFound(projectService.getProject(outsider, tenant.org.id, "secret"));
    await rejectsNotFound(issueService.getIssue(outsider, tenant.org.id, secretIssue.id));
    await rejectsNotFound(issueService.getBoard(outsider, tenant.org.id, secret.id));
    await rejectsNotFound(commentService.getThread(outsider, tenant.org.id, secretIssue.id));
    await rejectsNotFound(
      attachmentService.listAttachments(outsider, tenant.org.id, secretIssue.id),
    );
  });

  it("answers a viewer with not-found rather than a permission error", async () => {
    await rejectsNotFound(
      projectService.getProject(tenant.actors.viewer, tenant.org.id, "secret"),
    );
  });

  it("serves the same reads to admins and staff", async () => {
    for (const actor of [tenant.actors.admin, tenant.actors.owner, staff]) {
      const found = await projectService.getProject(actor, tenant.org.id, "secret");
      expect(found.project.id).toBe(secret.id);
      const issue = await issueService.getIssue(actor, tenant.org.id, secretIssue.id);
      expect(issue.issue.id).toBe(secretIssue.id);
      const thread = await commentService.getThread(actor, tenant.org.id, secretIssue.id);
      expect(thread).toHaveLength(1);
    }
  });
});

describe("private project — writes", () => {
  it("refuses every write with not-found and changes nothing", async () => {
    const orgId = tenant.org.id;

    await rejectsNotFound(
      issueService.createIssue(outsider, issueInput(orgId, secret.id, { title: "Sneaky" })),
    );
    await rejectsNotFound(
      issueService.updateIssue(outsider, { orgId, issueId: secretIssue.id, title: "Hijacked" }),
    );
    await rejectsNotFound(
      issueService.changeIssueStatus(outsider, {
        orgId,
        issueId: secretIssue.id,
        status: "done",
      }),
    );
    await rejectsNotFound(
      issueService.moveIssue(outsider, {
        orgId,
        issueId: secretIssue.id,
        toStatus: "done",
        toIndex: 0,
      } as never),
    );
    await rejectsNotFound(
      issueService.assignIssue(outsider, {
        orgId,
        issueId: secretIssue.id,
        assigneeId: tenant.userIds.member,
      }),
    );
    await rejectsNotFound(issueService.archiveIssue(outsider, orgId, secretIssue.id));
    await rejectsNotFound(
      commentService.createComment(outsider, {
        orgId,
        issueId: secretIssue.id,
        body: "nope",
        parentId: null,
        mentionedUserIds: [],
      }),
    );
    await rejectsNotFound(
      commentService.updateComment(outsider, {
        orgId,
        commentId: secretComment.id,
        body: "edited",
      }),
    );
    await rejectsNotFound(
      commentService.deleteComment(outsider, { orgId, commentId: secretComment.id }),
    );
    await rejectsNotFound(
      projectService.updateProject(outsider, {
        orgId,
        projectId: secret.id,
        name: "Renamed",
      }),
    );
    await rejectsNotFound(
      projectService.archiveProject(outsider, {
        orgId,
        projectId: secret.id,
        archiveIssues: true,
      }),
    );
    await rejectsNotFound(projectService.restoreProject(outsider, orgId, secret.id));

    const issue = await issueRepo.findIssueById(orgId, secretIssue.id);
    expect(issue?.title).toBe("Hidden issue");
    expect(issue?.status).toBe("backlog");
    expect(issue?.assigneeId).toBeNull();
    expect(issue?.archivedAt).toBeNull();
    expect(await issueRepo.countIssues(orgId, secret.id)).toBe(1);

    const project = await projectRepo.findProjectById(orgId, secret.id);
    expect(project?.name).toBe("Secret");
    expect(project?.archivedAt).toBeNull();
  });
});

describe("private project — listings", () => {
  it("drops the project and its issues, and their totals, for an outsider", async () => {
    const projects = await projectService.listProjects(outsider, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(projects.items.map((entry) => entry.project.id)).toEqual([tenant.project.id]);
    expect(projects.total).toBe(1);

    const issues = await issueService.listIssues(outsider, {
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(issues.items.map((issue) => issue.id)).toEqual([openIssue.id]);
    expect(issues.total).toBe(1);
  });

  it("returns nothing, not an error, when filtering on the hidden project", async () => {
    const issues = await issueService.listIssues(outsider, {
      orgId: tenant.org.id,
      projectId: secret.id,
      limit: 25,
      cursor: null,
    });
    expect(issues.items).toEqual([]);
    expect(issues.total).toBe(0);
  });

  it("keeps everything in the lists for admins and staff", async () => {
    for (const actor of [tenant.actors.admin, tenant.actors.owner, staff]) {
      const projects = await projectService.listProjects(actor, {
        orgId: tenant.org.id,
        limit: 25,
        cursor: null,
      });
      expect(projects.total).toBe(2);

      const issues = await issueService.listIssues(actor, {
        orgId: tenant.org.id,
        limit: 25,
        cursor: null,
      });
      expect(issues.total).toBe(2);
    }
  });
});

describe("private project — membership and lead take effect immediately", () => {
