    await rejectsNotFound(projectService.getProject(viewer, orgId, "secret"));
    const after = await issueService.listIssues(viewer, { orgId, limit: 25, cursor: null });
    expect(after.total).toBe(1);
  });

  it("follows a change of lead", async () => {
    const orgId = tenant.org.id;
    const member = tenant.actors.member;

    await rejectsNotFound(projectService.getProject(member, orgId, "secret"));

    await projectService.updateProject(tenant.actors.admin, {
      orgId,
      projectId: secret.id,
      leadId: tenant.userIds.member,
    });
    await expect(projectService.getProject(member, orgId, "secret")).resolves.toBeDefined();

    await projectService.updateProject(tenant.actors.admin, {
      orgId,
      projectId: secret.id,
      leadId: tenant.userIds.admin,
    });
    await rejectsNotFound(projectService.getProject(member, orgId, "secret"));
  });

  it("hides a project the moment it becomes private, and shows it once it is not", async () => {
    const orgId = tenant.org.id;
    const member = tenant.actors.member;

    await projectService.updateProject(tenant.actors.admin, {
      orgId,
      projectId: tenant.project.id,
      visibility: "private",
    });
    await rejectsNotFound(projectService.getProject(member, orgId, tenant.project.slug));
    await rejectsNotFound(issueService.getIssue(member, orgId, openIssue.id));

    await projectService.updateProject(tenant.actors.admin, {
      orgId,
      projectId: tenant.project.id,
      visibility: "org",
    });
    await expect(
      projectService.getProject(member, orgId, tenant.project.slug),
    ).resolves.toBeDefined();
  });
});
